import React, { useState } from "react";
import axios from "../utils/axiosInstance";

export default function Search({ onAdd }) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const res = await axios.get(
        `/api/search?symbol=${encodeURIComponent(query)}`
      );
      setResults(res.data);
    } catch (err) {
      setError(err.response?.data?.message || err.message);
      setResults([]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="search-component">
      <div className="search-box">
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search eg: INFY, BSE, NIFTY 50"
          className="search-input"
          onKeyDown={(e) => e.key === "Enter" && handleSearch()}
        />
        <button
          onClick={handleSearch}
          disabled={loading}
          className="search-button">
          {loading ? "Searching..." : "Search"}
        </button>
      </div>
      {error && <p className="error">{error}</p>}
      <ul className="search-results">
        {results.map((stock) => (
          <li key={stock.symbol} className="result-item">
            <div className="info">
              <span className="symbol">{stock.symbol}</span>
              <span className="name">{stock.name}</span>
            </div>
            <div className="metrics">
              <span className="price">{stock.price}</span>
              <span className={stock.change >= 0 ? "up" : "down"}>
                {stock.change > 0 ? "+" : ""}
                {stock.change}%
              </span>
            </div>
            <button className="add-button" onClick={() => onAdd(stock)}>
              + Watchlist
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
